import { describe, expect, it, vi } from 'vitest';
import { siteSections } from '../src/lib/site-sections.ts';

// The citations module is generated by vite.config.ts when the site is built.
vi.mock('virtual:source-citations', () => ({ sourceCitations: {} }));

const { builtSections, sectionContents } = await import('#lib/server/section-contents.ts');

describe('the pages inside each section, for the sidebar', () => {
	it('can list every section the sidebar opens', () => {
		const opening = siteSections.filter((section) => section.opens).map((section) => section.link.slice(1));
		const essayParts = ['foundations', 'essays'];
		expect(opening.filter((name) => !essayParts.includes(name)).sort()).toEqual([...builtSections].sort());
		expect(siteSections.filter((section) => section.opens && !section.built)).toEqual([]);
	});

	it('lists each section’s pages with working addresses', async () => {
		expect((await sectionContents('nations'))?.map((item) => item.link)).toEqual(['/nations', '/nations/map', '/nations/timeline', '/nations/recourse', '/nations/data']);
		expect((await sectionContents('library'))?.[0]?.link).toBe('/copies');
		const glossary = (await sectionContents('glossary')) ?? [];
		expect(glossary.length).toBeGreaterThan(0);
		expect(glossary.every((item) => item.link.startsWith('/glossary/'))).toBe(true);
		expect((await sectionContents('stories'))?.[0]).toEqual({ label: 'All stories', link: '/stories' });
	});

	it('refuses a section it does not know', async () => {
		expect(await sectionContents('sponsor')).toBeUndefined();
		expect(await sectionContents('constructor')).toBeUndefined();
	});
});
